customPhraseDescTS:
// 根据属性名称值编写自定义短语描述，如："我的短语是"+attrs.xxx
// 使用下拉框组件的变量attrs.xxx有对应的attrs.xxxItems的属性以便获得标签名集合
// 获取自定义模块的数据名称的函数：getModuleDataName(moduleID:number,dataID:number):string;
// 获取各种列表内数据名称的函数：getTypeDataListName(typeID: number, dataID: number):string;
// 获取自定义游戏数值描述的函数：getCustomGameNumber(customGameNumber: any[]):string;
// 获取自定义游戏字符串描述的函数：getCustomGameString(customGameString: any[]):string;
// 获取自定义游戏开关描述的函数：getCustomGameSwitch(customGameSwitch: any[]):string;
// -- typeID ：0-全局变量 1-全局开关 2-全局字符串 3-玩家变量 4-玩家开关 5-玩家字符串
//           ：6-场景列表 7-场景对象原型列表 8-图块列表 9-行走图列表 10-行走图动作列表 11-立绘列表 12-立绘表情列表
//           ：13-事件库列表 14-对话框列表 15-动画列表 16-动画信号列表 17-界面列表 18-数据结构列表 19-自定义模块列表
//           ：20-自定义指令列表 21-自定义行为列表 22-自动元件列表 23-行走图部件列表 24-立绘部件列表 25-材质列表 26-场景对象模块
var str = "";
str += attrs.soTypeItems[attrs.soType];
if (attrs.soType == 3) {
    str += ":";
    if (attrs.useVar) {
        str += ` [${attrs.soIndexVarID}-${getTypeDataListName(3, attrs.soIndexVarID)}]`;
    }
    else {
        str += ` ${attrs.soIndex}号`;
    }
}
if (attrs.type == 13) {
    let mapping = { 0: 3, 1: 5, 2: 4 };
    if (attrs.soCustomAttr.selectMode == 1) {
        let mode = attrs.soCustomAttr.inputModeInfo.mode;
        let constName = attrs.soCustomAttr.inputModeInfo.constName;
        let varNameIndex = attrs.soCustomAttr.inputModeInfo.varNameIndex;
        let varName = mode == 0 ? constName : `[@${varNameIndex}-${getTypeDataListName(mapping[varNameIndex], varNameIndex)}]`;
        str += " => 「" + varName + "」 已开启";
    }
    else {
        str += " => 「" + attrs.soCustomAttr.varName + "」 已开启";
    }
}
else if (attrs.type == 14) {
    if (attrs.soModuleType == 1) {
        str += ` ${attrs.soModuleTypeItems[attrs.soModuleType]} 「${attrs.soModuleID}-${getTypeDataListName(26, attrs.soModuleID)}」`
    }
    else {
        let mapping = { 0: 3, 1: 5, 2: 4 };
        if (attrs.soModuleAttr.selectMode == 1) {
            let mode = attrs.soModuleAttr.inputModeInfo.mode;
            let constName = attrs.soModuleAttr.inputModeInfo.constName;
            let varNameIndex = attrs.soModuleAttr.inputModeInfo.varNameIndex;
            let varName = mode == 0 ? constName : `[@${varNameIndex}-${getTypeDataListName(mapping[varNameIndex], varNameIndex)}]`;
            str += ` 模块「${attrs.soModuleAttr.moduleID}-${getTypeDataListName(26, attrs.soModuleAttr.moduleID)}」.${varName} 已开启`;
        }
        else {
            str += ` 模块「${attrs.soModuleAttr.moduleID}-${getTypeDataListName(26, attrs.soModuleAttr.moduleID)}」.${attrs.soModuleAttr.varName} 已开启`;
        }
    }
}
else {
    str += " => " + attrs.typeItems[attrs.type];
    switch (attrs.type) {
        case 22:
            str += attrs.skillUseVar ? `「${attrs.skillIDVarID}-${getTypeDataListName(3, attrs.skillIDVarID)}」` : `「${attrs.skillID}-${getModuleDataName(8, attrs.skillID)}」`;
            break;
        case 23:
            str += attrs.equipUseVar ? `「${attrs.equipIDVarID}-${getTypeDataListName(3, attrs.equipIDVarID)}」` : `「${attrs.equipID}-${getModuleDataName(9, attrs.equipID)}」`;
            break;
        case 24:
            str += attrs.itemUseVar ? `「${attrs.itemIDVarID}-${getTypeDataListName(3, attrs.itemIDVarID)}」` : `「${attrs.itemID}-${getModuleDataName(1, attrs.itemID)}」`;
            break;
        case 25:
            str += attrs.statusUseVar ? `「${attrs.statusIDVarID}-${getTypeDataListName(3, attrs.statusIDVarID)}」` : `「${attrs.statusID}-${getModuleDataName(10, attrs.statusID)}」`;
            str += attrs.statusLayer + "层以上"
            break;
        case 26:
            str += attrs.classUseVar ? `「${attrs.classIDVarID}-${getTypeDataListName(3, attrs.classIDVarID)}」` : `「${attrs.classID}-${getModuleDataName(7, attrs.classID)}」`;
            break;
    }
}
str;

customPhraseDescJS:
var str = "";
str += attrs.soTypeItems[attrs.soType];
if (attrs.soType == 3) {
    str += ":";
    if (attrs.useVar) {
        str += " [" + attrs.soIndexVarID + "-" + getTypeDataListName(3, attrs.soIndexVarID) + "]";
    }
    else {
        str += " " + attrs.soIndex + "\u53F7";
    }
}
if (attrs.type == 13) {
    var mapping = { 0: 3, 1: 5, 2: 4 };
    if (attrs.soCustomAttr.selectMode == 1) {
        var mode = attrs.soCustomAttr.inputModeInfo.mode;
        var constName = attrs.soCustomAttr.inputModeInfo.constName;
        var varNameIndex = attrs.soCustomAttr.inputModeInfo.varNameIndex;
        var varName = mode == 0 ? constName : "[@" + varNameIndex + "-" + getTypeDataListName(mapping[varNameIndex], varNameIndex) + "]";
        str += " => 「" + varName + "」 已开启";
    }
    else {
        str += " => 「" + attrs.soCustomAttr.varName + "」 已开启";
    }
}
else if (attrs.type == 14) {
    if (attrs.soModuleType == 1) {
        str += " " + attrs.soModuleTypeItems[attrs.soModuleType] + " \u300C" + attrs.soModuleID + "-" + getTypeDataListName(26, attrs.soModuleID) + "\u300D";
    }
    else {
        var mapping = { 0: 3, 1: 5, 2: 4 };
        if (attrs.soModuleAttr.selectMode == 1) {
            var mode = attrs.soModuleAttr.inputModeInfo.mode;
            var constName = attrs.soModuleAttr.inputModeInfo.constName;
            var varNameIndex = attrs.soModuleAttr.inputModeInfo.varNameIndex;
            var varName = mode == 0 ? constName : "[@" + varNameIndex + "-" + getTypeDataListName(mapping[varNameIndex], varNameIndex) + "]";
            str += " \u6A21\u5757\u300C" + attrs.soModuleAttr.moduleID + "-" + getTypeDataListName(26, attrs.soModuleAttr.moduleID) + "\u300D." + varName + " \u5DF2\u5F00\u542F";
        }
        else {
            str += " \u6A21\u5757\u300C" + attrs.soModuleAttr.moduleID + "-" + getTypeDataListName(26, attrs.soModuleAttr.moduleID) + "\u300D." + attrs.soModuleAttr.varName + " \u5DF2\u5F00\u542F";
        }
    }
}
else {
    str += " => " + attrs.typeItems[attrs.type];
    switch (attrs.type) {
        case 22:
            str += attrs.skillUseVar ? "\u300C" + attrs.skillIDVarID + "-" + getTypeDataListName(3, attrs.skillIDVarID) + "\u300D" : "\u300C" + attrs.skillID + "-" + getModuleDataName(8, attrs.skillID) + "\u300D";
            break;
        case 23:
            str += attrs.equipUseVar ? "\u300C" + attrs.equipIDVarID + "-" + getTypeDataListName(3, attrs.equipIDVarID) + "\u300D" : "\u300C" + attrs.equipID + "-" + getModuleDataName(9, attrs.equipID) + "\u300D";
            break;
        case 24:
            str += attrs.itemUseVar ? "\u300C" + attrs.itemIDVarID + "-" + getTypeDataListName(3, attrs.itemIDVarID) + "\u300D" : "\u300C" + attrs.itemID + "-" + getModuleDataName(1, attrs.itemID) + "\u300D";
            break;
        case 25:
            str += attrs.statusUseVar ? "\u300C" + attrs.statusIDVarID + "-" + getTypeDataListName(3, attrs.statusIDVarID) + "\u300D" : "\u300C" + attrs.statusID + "-" + getModuleDataName(10, attrs.statusID) + "\u300D";
            str += attrs.statusLayer + "层以上";
            break;
        case 26:
            str += attrs.classUseVar ? "\u300C" + attrs.classIDVarID + "-" + getTypeDataListName(3, attrs.classIDVarID) + "\u300D" : "\u300C" + attrs.classID + "-" + getModuleDataName(7, attrs.classID) + "\u300D";
            break;
    }
}
str;
